from itertools import combinations, product
import sys, time

def clause_mask(c, n):
    m = 0
    for a in range(1<<n):
        if sum((a>>v)&1 for v in c) == 1:
            m |= (1<<a)
    return m

def search(base, n_aux, maxsize, allowed, forbidden, timelimit=120):
    n = base + n_aux
    clauses = list(combinations(range(n),3))
    masks = [clause_mask(c,n) for c in clauses]
    projs = list(product([0,1],repeat=base))
    t0=time.time()
    for size in range(1,maxsize+1):
        cnt=0
        for idxs in combinations(range(len(clauses)), size):
            cnt+=1
            if cnt % 20000 == 0 and time.time()-t0>timelimit:
                return ('TIMEOUT', size)
            m = (1<<(1<<n))-1
            for i in idxs:
                m &= masks[i]
                if m==0: break
            if m==0: continue
            ok=True
            for proj in projs:
                # check if any full assignment with this projection is in m
                exists=False
                for aux in range(1<<n_aux):
                    full = proj[0] | (proj[1]<<1) | (proj[2]<<2) if base==3 else None
                    # generic
                    break
                # generic check
                exists=False
                for aux in range(1<<n_aux):
                    full=0
                    for b in range(base):
                        if proj[b]: full |= (1<<b)
                    for b in range(n_aux):
                        if (aux>>b)&1: full |= (1<<(base+b))
                    if (m>>full)&1:
                        exists=True;break
                want = proj in allowed
                if exists != want:
                    ok=False;break
            if ok:
                return [clauses[i] for i in idxs]
    return None

allowed_or = set(product([0,1],repeat=3)) - {(0,0,0)}
print("OR3 n_aux=3:", search(3,3,8,allowed_or,{(0,0,0)},60))
EOF
