from itertools import combinations, product
import time

def clause_mask(c, n):
    m = 0
    for a in range(1<<n):
        if sum((a>>v)&1 for v in c) == 1:
            m |= (1<<a)
    return m

def search(base, n_aux, maxsize, allowed, forbidden, timelimit=180):
    n = base + n_aux
    clauses = list(combinations(range(n),3))
    masks = [clause_mask(c,n) for c in clauses]
    projs = list(product([0,1],repeat=base))
    proj_full = []
    for proj in projs:
        basebits = 0
        for b in range(base):
            if proj[b]: basebits |= (1<<b)
        fulls = [basebits | (aux<<base) for aux in range(1<<n_aux)]
        proj_full.append((proj, fulls))
    t0=time.time()
    for size in range(1,maxsize+1):
        cnt=0
        for idxs in combinations(range(len(clauses)), size):
            cnt+=1
            if cnt % 50000 == 0 and time.time()-t0>timelimit:
                return ('TIMEOUT', size)
            m = (1<<(1<<n))-1
            for i in idxs:
                m &= masks[i]
                if m==0: break
            if m==0: continue
            ok=True
            for proj, fulls in proj_full:
                exists = any((m>>f)&1 for f in fulls)
                want = proj in allowed
                if exists != want:
                    ok=False;break
            if ok:
                return [clauses[i] for i in idxs]
    return None

