from itertools import combinations, product
import time

# vars: 0=x,1=y,2=z,3=a,4=b,5=an,6=bn ; constraint a=1-an, b=1-bn
NV=7
def clause_mask(c):
    m=0
    for a in range(1<<NV):
        if ((a>>c[0])&1)+((a>>c[1])&1)+((a>>c[2])&1)==1:
            m|=1<<a
    return m
clauses=list(combinations(range(NV),3))
masks=[clause_mask(c) for c in clauses]

# precompute aux full assignments given (x,y,z) and a,b
def fulls(x,y,z,a,b):
    an=1-a; bn=1-b
    bits=[x,y,z,a,b,an,bn]
    f=0
    for i,bit in enumerate(bits):
        if bit: f|=1<<i
    return f

proj_full={}
for x in (0,1):
 for y in (0,1):
  for z in (0,1):
    lst=[]
    for a in (0,1):
     for b in (0,1):
        lst.append(fulls(x,y,z,a,b))
    proj_full[(x,y,z)]=lst

def check(m):
    for proj,lst in proj_full.items():
        ex=any((m>>f)&1 for f in lst)
        want = proj!=(0,0,0)
        if ex!=want: return False
    return True

t0=time.time()
for size in range(1,7):
    cnt=0
    for idxs in combinations(range(len(clauses)),size):
        cnt+=1
        m=(1<<(1<<NV))-1
        for i in idxs:
            m&=masks[i]
            if m==0: break
        if m==0: continue
        if check(m):
            print("FOUND size",size,[clauses[i] for i in idxs]); raise SystemExit
    print("size",size,"done",cnt,"time",round(time.time()-t0,1),flush=True)
print("none")
