import random
from itertools import combinations, product

def build(nv, base, aux_pairs):
    # aux_pairs: list of (pos,neg) var indices; base vars 0..base-1
    clauses=list(combinations(range(nv),3))
    masks=[]
    for c in clauses:
        m=0
        for a in range(1<<nv):
            if ((a>>c[0])&1)+((a>>c[1])&1)+((a>>c[2])&1)==1:
                m|=1<<a
        masks.append(m)
    # projection -> list of full assignments
    pf={}
    for proj in product([0,1],repeat=base):
        lst=[]
        for auxbits in product([0,1],repeat=len(aux_pairs)):
            f=0
            for b in range(base):
                if proj[b]: f|=1<<b
            for (p,n),val in zip(aux_pairs,auxbits):
                if val: f|=1<<p
                else: f|=1<<n
            lst.append(f)
        pf[proj]=lst
    return clauses,masks,pf

def check(m,pf):
    for proj,lst in pf.items():
        ex=any((m>>f)&1 for f in lst)
        if ex!=(proj!=(0,0,0)): return False
    return True

random.seed(1)
for naux in [2,3,4]:
