int found=0;

// projections: for base vars, allowed set = all except all-zero (OR3)
int allowed[8]; // indexed by base bits

int clause_mask(int c, unsigned long long m[2]){
    m[0]=0;m[1]=0;
    for(int a=0;a<(1<<NV);a++){
        int s=((a>>cl[c][0])&1)+((a>>cl[c][1])&1)+((a>>cl[c][2])&1);
        if(s==1){ if(a<64) m[0]|=1ULL<<a; else m[1]|=1ULL<<(a-64);}
    }
    return 0;
}

int check(unsigned long long m[2]){
    // for each projection p (base bits), exists aux s.t. full assignment in m
    for(int p=0;p<(1<<BASE);p++){
        int want = (p!=0); // OR3: allowed all nonzero
        int ex=0;
        // enumerate aux assignments
        for(int aux=0; aux<(1<<NAUX); aux++){
            int full = p | (aux<<BASE);
            int bit = (full<64)? ((m[0]>>full)&1) : ((m[1]>>(full-64))&1);
            if(bit){ex=1;break;}
        }
        if(ex!=want) return 0;
    }
    return 1;
}

