        unsigned long long nm[2];
        nm[0]=m[0]&mask[i][0]; nm[1]=m[1]&mask[i][1];
        if(nm[0]==0 && nm[1]==0) continue;
        sol[soln++]=i;
        dfs(i+1, depth+1, nm);
        soln--;
        if(found) return;
    }
}

int main(int argc,char**argv){
    BASE=3; NAUX=atoi(argv[1]); MAXSIZE=atoi(argv[2]);
