        cl[nclauses][0]=a;cl[nclauses][1]=b;cl[nclauses][2]=c;
        clause_mask(nclauses, mask[nclauses]);
        nclauses++;
    }
    printf("NV=%d nclauses=%d MAXSIZE=%d\n",NV,nclauses,MAXSIZE);
    unsigned long long full[2]={~0ULL, (1ULL<<(1<<NV))-1};
    if((1<<NV)<64) full[1]=0;
    // careful: if 1<<NV <=64, only m[0] used
    if((1<<NV)<=64){ full[0]=(1ULL<<(1<<NV))-1; full[1]=0; }
