#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int NV, BASE, MAXSIZE, NAUX;
int ncl;
int cl[5000][3];      // variable indices
int clsign[5000][3];  // 1 = positive, 0 = negative
unsigned long long mask[5000][2];
int allowed[8];       // allowed[baseproj] = 1 if that projection is allowed
int sol[64], soln;
int found=0;
long long nodes=0;

void cmask(int c, unsigned long long m[2]){
    m[0]=0;m[1]=0;
    for(int a=0;a<(1<<NV);a++){
        int s=0;
        for(int j=0;j<3;j++){
            int v=cl[c][j];
            int bit=(a>>v)&1;
            if(!clsign[c][j]) bit^=1;
            s+=bit;
        }
        if(s==1){ if(a<64) m[0]|=1ULL<<a; else m[1]|=1ULL<<(a-64); }
    }
}

// returns 1 if projection set of mask == allowed exactly
// also sets *missing if some allowed proj missing (prune)
int proj_ok(unsigned long long m[2], int *missing){
    *missing=0;
    for(int p=0;p<(1<<BASE);p++){
        int ex=0;
        for(int aux=0;aux<(1<<NAUX);aux++){
            int full=p|(aux<<BASE);
            int bit=(full<64)?((m[0]>>full)&1):((m[1]>>(full-64))&1);
            if(bit){ex=1;break;}
        }
        if(ex && !allowed[p]) return 0;      // extra projection -> invalid (can't fix)
        if(!ex && allowed[p]){ *missing=1; return 0; } // missing -> prune
    }
    return 1;
}

void dfs(int start,int depth,unsigned long long m[2]){
    nodes++;
    int missing;
    if(depth>0){
        int r=proj_ok(m,&missing);
        if(r){ found=1; return; }
        if(missing) return; // prune
        // else: extra projection present, can't fix by adding -> prune too
        return;
    }
    if(depth==MAXSIZE) return;
    for(int i=start;i<ncl && !found;i++){
        unsigned long long nm[2]={m[0]&mask[i][0], m[1]&mask[i][1]};
        if(nm[0]==0 && nm[1]==0) continue;
        sol[soln++]=i;
        dfs(i+1,depth+1,nm);
        soln--;
        if(found) return;
    }
}

int main(int argc,char**argv){
    BASE=atoi(argv[1]); NAUX=atoi(argv[2]); MAXSIZE=atoi(argv[3]);
    int mode=atoi(argv[4]); // 0=OR3, 1=OR2out, 2=AND2out
    NV=BASE+NAUX;
    memset(allowed,0,sizeof(allowed));
    if(mode==0){ for(int p=0;p<(1<<BASE);p++) allowed[p]=(p!=0); }
    else if(mode==1){ // base 3: (a,b,o) o=a|b
        for(int p=0;p<8;p++){int a=p&1,b=(p>>1)&1,o=(p>>2)&1; if(o==(a|b)) allowed[p]=1;}
    }
    else if(mode==2){ // (a,b,o) o=a&b
        for(int p=0;p<8;p++){int a=p&1,b=(p>>1)&1,o=(p>>2)&1; if(o==(a&b)) allowed[p]=1;}
    }
    ncl=0;
    for(int a=0;a<NV;a++)for(int b=a+1;b<NV;b++)for(int c=b+1;c<NV;c++){
        for(int s=0;s<8;s++){
            cl[ncl][0]=a;cl[ncl][1]=b;cl[ncl][2]=c;
            clsign[ncl][0]=(s&1)?1:0;clsign[ncl][1]=(s&2)?1:0;clsign[ncl][2]=(s&4)?1:0;
            cmask(ncl,mask[ncl]);
            ncl++;
        }
    }
    unsigned long long full[2];
    if((1<<NV)<=64){ full[0]=(1ULL<<(1<<NV))-1; full[1]=0; }
    else { full[0]=~0ULL; full[1]=(1ULL<<((1<<NV)-64))-1; }
    soln=0; found=0; nodes=0;
    dfs(0,0,full);
    if(found){
        printf("FOUND size=%d:",soln);
        for(int i=0;i<soln;i++){
            printf(" (");
            for(int j=0;j<3;j++) printf("%s%d",clsign[sol[i]][j]?"":"-",cl[sol[i]][j]);
            printf(")");
        }
        printf("\n");
    } else printf("none nodes=%lld ncl=%d\n",nodes,ncl);
    return 0;
}
